const RE = /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?$/;
function bad(s){ return !s || typeof s !== "string" || !RE.test(s); }
const i = $input.first().json;
if (bad(i.namespace) || bad(i.name)) return [{json: {blocked: true, ok: false, detail: "invalid or missing namespace/name"}}];
const kinds = {deployment: "deployments", statefulset: "statefulsets", daemonset: "daemonsets"};
const kind = String(i.kind || "deployment").toLowerCase().replace(/s$/, "");
const res = kinds[kind]; if (!res) return [{json: {blocked: true, ok: false, detail: "kind must be deployment, statefulset or daemonset"}}];
return [{json: {url: `https://kubernetes.default.svc/apis/apps/v1/namespaces/${i.namespace}/${res}/${i.name}`, kind}}];

const r = $input.first().json;
if (r.blocked) return [{json: {ok: false, detail: r.detail}}];
if (r.statusCode >= 400) return [{json: {ok: false, detail: `K8s API ${r.statusCode}: ${JSON.stringify(r.body?.message).slice(0,200)}`}}];
const d = r.body; const st = d.status || {};
return [{json: {ok: true, workload: {
  kind: d.kind, name: d.metadata.name, namespace: d.metadata.namespace,
  replicas: {desired: d.spec.replicas ?? st.desiredNumberScheduled, ready: st.readyReplicas ?? st.numberReady ?? 0, available: st.availableReplicas ?? st.numberAvailable ?? 0, updated: st.updatedReplicas ?? st.updatedNumberScheduled ?? 0},
  strategy: d.spec.strategy?.type || d.spec.updateStrategy?.type,
  nodeSelector: d.spec.template.spec.nodeSelector, hostNetwork: !!d.spec.template.spec.hostNetwork,
  containers: (d.spec.template.spec.containers||[]).map(c => ({name: c.name, image: c.image, resources: c.resources, env: (c.env||[]).filter(e => /JAVA|OPTS|XMX|MEM|HEAP/i.test(e.name)).map(e => `${e.name}=${e.value||"(ref)"}`)})),
  conditions: (st.conditions||[]).map(c => `${c.type}=${c.status} (${c.reason||""})`)
}}}];
